package dev.codex.schubert.nk.api.maintenance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** NK-OPS-001; RD SYS-002/004, OPS-009; UI212/231/243/251/253; SS342/343; PG269/274/277. */
final class ApplicationServiceUnitTest {
  private static final Path ROOT = Path.of(System.getProperty("nk.pt.repository"));
  private static final Path UNITS = ROOT.resolve("src/deployment/systemd");
  @TempDir Path temporary;

  @Test
  void apiDependencyCredentialAndResourceContract() throws Exception {
    String unit = read("schubert-nk-api");
    common(unit, "api", "2048M", "60s", "512m", "1024m", "256m", "256m");
    // SSC099/BUG307: SS341§2 independent complete Unit name, not SS342's old shorthand.
    exact(unit, "After", "schubert-nk-expiry-cleanup.service artemis.service postgresql.service");
    // SSC139/BUG398: ordering is retained; the parent alone starts owned maintenance.
    exact(unit, "Requires", "artemis.service postgresql.service");
    exact(unit, "SupplementaryGroups", "schubert schubert-read schubert-web");
    exact(unit, "ReadWritePaths", "/srv/schubert-nk/data/transfer");
    credentials(
        unit,
        "db-api",
        "mq-api",
        "api-context-aes-current",
        "api-inbox-response-aes-current",
        "operation-hmac-current");
    assertTrue(unit.contains("dev.codex.schubert.nk.batch.file.RootServiceLauncher API"));
    assertFalse(unit.contains("dev.codex.schubert.nk.api.bootstrap.ApiProcessMain"));
    assertFalse(unit.contains("LoadCredential=web-session-aes"));
    assertFalse(unit.contains("ReadWritePaths=/srv/schubert-nk/data/assets"));
    exactEnvTemplate("api");
  }

  @Test
  void webDependencyCredentialAndResourceContract() throws Exception {
    String unit = read("schubert-nk-web");
    common(unit, "web", "1536M", "30s", "384m", "768m", "128m", "192m");
    exact(unit, "After", "schubert-nk-api.service artemis.service postgresql.service");
    exact(unit, "Requires", "schubert-nk-api.service artemis.service postgresql.service");
    exact(unit, "SupplementaryGroups", "schubert schubert-read");
    assertFalse(unit.contains("ReadWritePaths="));
    credentials(
        unit,
        "db-web",
        "mq-web",
        "web-session-aes-current",
        "web-revoke-aes-current",
        "web-log-aes-current");
    assertTrue(unit.contains("dev.codex.schubert.nk.batch.file.RootServiceLauncher WEB"));
    assertFalse(unit.contains("dev.codex.schubert.nk.web.bootstrap.WebProcessMain"));
    assertFalse(unit.contains("LoadCredential=api-context-aes"));
    assertFalse(unit.contains("LoadCredential=operation-hmac"));
    exactEnvTemplate("web");
  }

  @Test
  void noSecretInEnvironmentOrShellAndNoAutomaticWritableEscalation() throws Exception {
    for (String service : List.of("api", "web")) {
      String unit = read("schubert-nk-" + service);
      for (String line : unit.lines().toList()) {
        if (line.startsWith("#")) continue;
        assertFalse(line.startsWith("Environment="));
        assertFalse(line.contains("sh -c"));
        assertFalse(line.contains("/bin/sh"));
        assertFalse(line.contains("SetCredential="));
        assertFalse(line.contains("PassEnvironment="));
        assertFalse(line.contains("+ExecStart="));
      }
      exact(unit, "ProtectSystem", "strict");
      exact(unit, "ProtectHome", "true");
      exact(unit, "SendSIGKILL", "no");
      exact(unit, "NoNewPrivileges", "true");
      exact(unit, "RestrictAddressFamilies", "AF_UNIX AF_INET AF_INET6");
      assertEquals(1, unit.lines().filter(line -> line.startsWith("ExecStart=")).count());
      assertEquals(5, unit.lines().filter(line -> line.startsWith("LoadCredential=")).count());
    }
  }

  @Test
  void renderedSyntaxIsAcceptedWithoutStartingService() throws Exception {
    for (String service : List.of("api", "web")) {
      String name = "schubert-nk-" + service;
      Path directory = Files.createDirectory(temporary.resolve(service));
      String unit = read(name);
      String executable =
          unit.lines().filter(line -> line.startsWith("ExecStart=")).findFirst().orElseThrow();
      Files.writeString(
          directory.resolve(name + ".service"),
          unit.replace(executable, "ExecStart=/bin/true")
              .replace(
                  "WorkingDirectory=/opt/schubert-nk/current/" + service,
                  "WorkingDirectory=" + directory));
      for (String dependency :
          List.of("schubert-nk-expiry-cleanup", "artemis", "postgresql", "schubert-nk-api")) {
        Files.writeString(
            directory.resolve(dependency + ".service"),
            "[Service]\nType=oneshot\nExecStart=/bin/true\n");
      }
      ProcessBuilder process =
          new ProcessBuilder(
              "/usr/bin/systemd-analyze",
              "verify",
              "--man=no",
              directory.resolve(name + ".service").toString());
      process.environment().clear();
      process.environment().putAll(UnitSyntaxFixture.environment(directory));
      process.redirectErrorStream(true);
      Process running = process.start();
      assertTrue(running.waitFor(Duration.ofSeconds(10)));
      String output = new String(running.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
      assertEquals(0, running.exitValue(), output);
      assertEquals("", output);
    }
  }

  @Test
  void isolatedLookupStillReportsProjectSyntaxWarnings() throws Exception {
    Path directory = Files.createDirectory(temporary.resolve("negative"));
    Path unit = directory.resolve("negative.service");
    Files.writeString(
        unit,
        "[Service]\nType=oneshot\nExecStart=/bin/true\nNKInvalidDirectiveForNegativeOracle=yes\n");
    ProcessBuilder process =
        new ProcessBuilder("/usr/bin/systemd-analyze", "verify", "--man=no", unit.toString());
    process.environment().clear();
    process.environment().putAll(UnitSyntaxFixture.environment(directory));
    process.redirectErrorStream(true);
    Process running = process.start();
    assertTrue(running.waitFor(Duration.ofSeconds(10)));
    String output = new String(running.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
    // systemd returns zero for unknown directives, so exit zero alone is never
    // a successful syntax oracle. Positive cases above require empty output.
    assertEquals(0, running.exitValue());
    assertTrue(output.contains("Unknown key 'NKInvalidDirectiveForNegativeOracle'"));
    assertTrue(output.contains("negative.service"));
    assertFalse(output.contains("xfs_scrub_all.service"));
  }

  private static String read(String name) throws Exception {
    return Files.readString(UNITS.resolve(name + ".service.template"));
  }

  private static void exactEnvTemplate(String service) throws Exception {
    byte[] actual =
        Files.readAllBytes(ROOT.resolve("src/deployment/config/" + service + ".env.template"));
    assertTrue(
        java.util.Arrays.equals(
            "SCHUBERT_NK_CONFIG_DIR=/etc/schubert-nk\n".getBytes(StandardCharsets.US_ASCII),
            actual));
  }

  private static void exact(String unit, String key, String value) {
    List<String> found = new ArrayList<>();
    for (String line : unit.lines().toList()) {
      if (line.startsWith(key + "=")) found.add(line.substring(key.length() + 1));
    }
    assertEquals(List.of(value), found, key);
  }

  private static void credentials(String unit, String... ids) {
    List<String> actual = unit.lines().filter(line -> line.startsWith("LoadCredential=")).toList();
    List<String> expected = new ArrayList<>();
    for (String id : ids) {
      expected.add("LoadCredential=" + id + ":/etc/schubert-nk/credentials/" + id);
    }
    assertEquals(expected, actual);
  }

  private static void common(
      String unit,
      String service,
      String memory,
      String stop,
      String xms,
      String xmx,
      String direct,
      String metaspace) {
    exact(unit, "Type", "simple");
    exact(unit, "User", "schubert-" + service);
    exact(unit, "Group", "schubert-" + service);
    exact(unit, "WorkingDirectory", "/opt/schubert-nk/current/" + service);
    exact(unit, "EnvironmentFile", "/etc/schubert-nk/" + service + ".env");
    exact(unit, "Restart", "on-failure");
    exact(unit, "RestartSec", "5s");
    exact(unit, "StartLimitIntervalSec", "600");
    exact(unit, "StartLimitBurst", "5");
    exact(unit, "TimeoutStartSec", "120s");
    exact(unit, "TimeoutStopSec", stop);
    exact(unit, "MemoryMax", memory);
    exact(unit, "LimitNOFILE", "65536");
    exact(unit, "RuntimeDirectory", "schubert-nk/" + service);
    exact(unit, "UMask", "0027");
    // SS342/SSC137: ! keeps only this Root entry privileged; ordinary exec vectors are
    // independently fixed in FixedServiceExecArgumentsTest and drop every capability.
    exact(
        unit,
        "CapabilityBoundingSet",
        "CAP_SETUID CAP_SETGID CAP_SETPCAP CAP_SYS_PTRACE CAP_DAC_READ_SEARCH");
    assertTrue(
        unit.lines()
            .filter(line -> line.startsWith("ExecStart="))
            .findFirst()
            .orElseThrow()
            .startsWith("ExecStart=!/usr/bin/java "));
    String command =
        unit.lines().filter(line -> line.startsWith("ExecStart=")).findFirst().orElseThrow();
    for (String fixed :
        List.of(
            "/usr/bin/java",
            "--enable-native-access=ALL-UNNAMED",
            "-Dfile.encoding=UTF-8",
            "-Duser.timezone=UTC",
            "-XX:+ExitOnOutOfMemoryError",
            "-XX:MaxDirectMemorySize=" + direct,
            "-XX:MaxMetaspaceSize=" + metaspace,
            "-XX:ReservedCodeCacheSize=128m",
            "-Xms" + xms,
            "-Xmx" + xmx,
            "-Xlog:gc*=info:stdout:time,uptime,level,tags")) {
      assertTrue(command.contains(fixed), fixed);
    }
  }
}

package dev.codex.schubert.nk.api.maintenance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.codex.schubert.nk.api.idempotency.InboxResultReference;
import dev.codex.schubert.nk.api.idempotency.ResponseSnapshotCodec;
import dev.codex.schubert.nk.api.idempotency.ResponseSnapshotIdentity;
import dev.codex.schubert.nk.api.logging.ApiLogDatabaseFixture;
import dev.codex.schubert.nk.bootstrap.MaintenanceOwnerFrame;
import java.io.IOException;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * PT-DB-INBOX-033..040: real least-privilege PG and independent JCE/wire, never production capture.
 */
final class AuthenticationInboxCleanupTest {
  @TempDir static Path root;
  private static ApiLogDatabaseFixture db;
  private static String url;
  private static final UUID MESSAGE = new UUID(0, 101);
  private static final UUID SESSION = new UUID(0, 104);
  private static final InspectionRun RUN =
      new InspectionRun(new UUID(0, 42), Instant.parse("2026-09-17T00:00:00.123Z"));
  private static final ResponseSnapshotIdentity LOGIN =
      ResponseSnapshotIdentity.anonymous(MESSAGE, "LGNRSP01", "001");
  private static final ResponseSnapshotIdentity LOGOUT =
      ResponseSnapshotIdentity.authenticated(MESSAGE, "LOGRSP01", "001", 7);

  @BeforeAll
  static void start() throws Exception {
    db = new ApiLogDatabaseFixture(root);
    try (var c = db.api()) {
      url = c.getMetaData().getURL();
    }
  }

  @AfterAll
  static void stop() throws Exception {
    if (db != null) db.stop();
  }

  @BeforeEach
  void reset() throws SQLException {
    for (String table :
        List.of("request_inbox", "auth_sessions", "app_logs", "batch_runs", "app_users"))
      sql("delete from schubert." + table);
    sql(
        "insert into schubert.app_users(id,username,username_key,password_hash,role,status,password_changed_at,created_at,updated_at) values(7,'Learner','learner','synthetic-unused','USER','ACTIVE','2026-09-09','2026-09-09','2026-09-09')");
    try (var c = db.api();
        var s =
            c.prepareStatement(
                "insert into schubert.batch_runs(run_id,business_date,step,attempt,started_at,ended_at,status) values (?,'2026-09-17',?,1,'2026-09-17T00:00:00Z','2026-09-17T00:00:01Z','SUCCESS')")) {
      for (String step : List.of("BACKUP_DB", "BACKUP_CONFIG")) {
        s.setObject(1, RUN.id());
        s.setString(2, step);
        assertEquals(1, s.executeUpdate());
      }
    }
  }

  @Test
  void validAuthRowsDeleteAtomically() throws Exception {
    for (var id : List.of(LOGIN, LOGOUT)) {
      for (String code :
          id.equals(LOGIN) ? List.of("0000", "0101", "0106") : List.of("0000", "0200", "0102")) {
        reset();
        try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
          seed(f, id, code);
          String before = references();
          var service = service(f);
          assertEquals(
              new InspectionStep(InspectionStep.Outcome.DELETED, Optional.of(MESSAGE)),
              service.inspectNext(RUN, Optional.empty()));
          assertEquals("0", count());
          assertEquals(before, references());
          assertEquals(
              new InspectionStep(InspectionStep.Outcome.END, Optional.empty()),
              service.inspectNext(RUN, Optional.empty()));
        }
      }
    }
  }

  @Test
  void invalidRowsAreProtectedWithoutMutation() throws Exception {
    for (String mutation :
        List.of(
            "update schubert.request_inbox set response_body_encrypted=decode(repeat('00',30),'hex')",
            "update schubert.request_inbox set response_key_version='unknown'",
            "delete from schubert.auth_sessions",
            "update schubert.auth_sessions set context_hash=repeat('b',64)",
            "update schubert.request_inbox set fingerprint_key_version='unknown'",
            "update schubert.request_inbox set request_version='002'",
            "update schubert.request_inbox set response_version='002'",
            "update schubert.request_inbox set response_layout_id='LOGRSP01'",
            "update schubert.request_inbox set expires_at=completed_at+interval '1 hour'",
            "update schubert.request_inbox set response_body_encrypted=null,response_key_version=null")) {
      reset();
      try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
        seed(f, LOGIN, "0000");
        sql(mutation);
        assertEquals(
            InspectionStep.Outcome.PROTECTED,
            service(f).inspectNext(RUN, Optional.empty()).outcome(),
            mutation);
        assertEquals("1", count());
      }
    }
    for (String mutation :
        List.of(
            "expires_at='2026-09-17T00:00:00.123Z'",
            "request_layout_id='GAMREQ01',owner_user_id=7,response_layout_id='GAMRSP01'",
            "processing_state='PROCESSING',completed_at=null,result_ref_type=null,result_ref_uuid=null,response_layout_id=null,response_version=null,response_body_encrypted=null,response_key_version=null")) {
      reset();
      try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
        seed(f, LOGIN, "0000");
        sql("update schubert.request_inbox set " + mutation);
        assertEquals(
            mutation.contains("GAMREQ01")
                ? InspectionStep.Outcome.PROTECTED
                : InspectionStep.Outcome.END,
            service(f).inspectNext(RUN, Optional.empty()).outcome());
        assertEquals("1", count());
      }
    }
  }

  @Test
  void nullUnknownAndFactoryContracts() throws Exception {
    assertThrows(NullPointerException.class, () -> new InspectionRun(null, RUN.cutoff()));
    assertThrows(NullPointerException.class, () -> new InspectionRun(RUN.id(), null));
    for (Instant cutoff : List.of(Instant.MIN, Instant.MAX, RUN.cutoff().plusNanos(1)))
      assertThrows(IllegalArgumentException.class, () -> new InspectionRun(RUN.id(), cutoff));
    for (Instant cutoff :
        List.of(
            Instant.parse("0001-01-01T00:00:00Z"), Instant.parse("9999-12-31T23:59:59.999999Z")))
      assertEquals(cutoff, new InspectionRun(RUN.id(), cutoff).cutoff());
    assertThrows(NullPointerException.class, () -> new InspectionStep(null, Optional.empty()));
    assertThrows(
        NullPointerException.class, () -> new InspectionStep(InspectionStep.Outcome.END, null));
    assertThrows(
        IllegalArgumentException.class,
        () -> new InspectionStep(InspectionStep.Outcome.END, Optional.of(MESSAGE)));
    assertThrows(
        IllegalArgumentException.class,
        () -> new InspectionStep(InspectionStep.Outcome.PROTECTED, Optional.empty()));
    try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
      assertThrows(
          NullPointerException.class,
          () ->
              new InboxCleanup(
                  null,
                  f.inspector,
                  new NonAuthenticationInboxInspector(f.snapshots),
                  Set.of("v1")));
      assertThrows(
          NullPointerException.class,
          () ->
              new InboxCleanup(
                  AuthenticationInboxCleanupTest::connection,
                  null,
                  new NonAuthenticationInboxInspector(f.snapshots),
                  Set.of("v1")));
      assertThrows(
          NullPointerException.class,
          () ->
              new InboxCleanup(
                  AuthenticationInboxCleanupTest::connection,
                  f.inspector,
                  new NonAuthenticationInboxInspector(f.snapshots),
                  null));
      var nullElement = new HashSet<String>();
      nullElement.add(null);
      assertThrows(
          NullPointerException.class,
          () ->
              new InboxCleanup(
                  AuthenticationInboxCleanupTest::connection,
                  f.inspector,
                  new NonAuthenticationInboxInspector(f.snapshots),
                  nullElement));
      for (Set<String> versions :
          List.of(Set.<String>of(), Set.of(""), Set.of("v1", "bad secret value")))
        assertThrows(
            IllegalArgumentException.class,
            () ->
                new InboxCleanup(
                    AuthenticationInboxCleanupTest::connection,
                    f.inspector,
                    new NonAuthenticationInboxInspector(f.snapshots),
                    versions));
      var versions = new HashSet<>(Set.of("v1", "previous"));
      var cleanup =
          new InboxCleanup(
              AuthenticationInboxCleanupTest::connection,
              f.inspector,
              new NonAuthenticationInboxInspector(f.snapshots),
              versions);
      versions.clear();
      assertThrows(NullPointerException.class, () -> cleanup.inspectNext(null, Optional.empty()));
      assertThrows(NullPointerException.class, () -> cleanup.inspectNext(RUN, null));
      seed(f, LOGIN, "0101");
      assertEquals(
          InspectionStep.Outcome.DELETED, cleanup.inspectNext(RUN, Optional.empty()).outcome());
    }
    for (String column :
        List.of(
            "message_id",
            "request_layout_id",
            "response_layout_id",
            "correlation_id",
            "created_at",
            "expires_at",
            "request_version",
            "response_version",
            "request_fingerprint_hmac",
            "fingerprint_key_version",
            "result_ref_type",
            "processing_state",
            "response_key_version",
            "completed_at",
            "inspection_xact",
            "inspection_hash")) {
      reset();
      try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
        seed(f, LOGIN, "0101");
        var probe = new MaintenanceJdbcProbe();
        probe.columns.put(column, null);
        redacted(() -> probed(f, probe).inspectNext(RUN, Optional.empty()));
        assertEquals("1", count(), column);
        assertEquals(1, probe.closes);
      }
    }
    Map<String, Object> malformed =
        Map.ofEntries(
            Map.entry("request_layout_id", "UNKNOWN1"),
            Map.entry("operation_token", new UUID(0, 77)),
            Map.entry("request_fingerprint_hmac", "Z".repeat(64)),
            Map.entry("owner_user_id", 7L),
            Map.entry("result_ref_type", "UNKNOWN"),
            Map.entry("processing_state", "UNKNOWN"),
            Map.entry("response_body_encrypted", new byte[1]),
            Map.entry("response_key_version", "bad key"),
            Map.entry("result_ref_id", 7L));
    for (var bad : malformed.entrySet()) {
      reset();
      try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
        seed(f, LOGIN, "0101");
        var probe = new MaintenanceJdbcProbe();
        probe.columns.put(bad.getKey(), bad.getValue());
        assertEquals(
            InspectionStep.Outcome.PROTECTED,
            probed(f, probe).inspectNext(RUN, Optional.empty()).outcome(),
            bad.getKey());
        assertEquals("1", count());
      }
    }
  }

  @Test
  void ownsTransactionAndKeepsLocks() throws Exception {
    try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
      seed(f, LOGIN, "0000");
      var probe = new MaintenanceJdbcProbe();
      probe.beforeDelete =
          c -> {
            assertFalse(c.getAutoCommit());
            assertEquals(0, probe.commits);
            assertEquals(0, probe.closes);
            for (String query :
                List.of(
                    "select message_id from schubert.request_inbox for update nowait",
                    "select id from schubert.auth_sessions for update nowait",
                    "select id from schubert.batch_runs for update nowait")) {
              try (var other = db.api();
                  var s = other.createStatement()) {
                assertEquals(
                    "55P03",
                    assertThrows(SQLException.class, () -> s.execute(query)).getSQLState());
              }
            }
          };
      assertEquals(
          InspectionStep.Outcome.DELETED,
          probed(f, probe).inspectNext(RUN, Optional.empty()).outcome());
      assertEquals(1, probe.commits);
      assertEquals(1, probe.closes);
      assertEquals(0, probe.rollbacks);
      assertEquals(0, probe.saves);
      assertEquals(1, probe.deletes);
    }
    try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
      var probe = new MaintenanceJdbcProbe();
      probe.fresh = false;
      redacted(() -> probed(f, probe).inspectNext(RUN, Optional.empty()));
      assertEquals(1, probe.closes);
      assertEquals(0, probe.deletes);
    }
  }

  @Test
  void failuresRollbackAndRemainRedacted() throws Exception {
    try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
      seed(f, LOGIN, "0101");
      var probe = new MaintenanceJdbcProbe();
      probe.columns.put("message_id", null);
      probe.fault = "rollback";
      redacted(() -> probed(f, probe).inspectNext(RUN, Optional.empty()));
      assertEquals(1, probe.rollbacks);
      assertEquals(1, probe.closes);
      assertEquals("1", count());
    }
    for (String fault :
        List.of(
            "getAutoCommit",
            "setAutoCommit",
            "prepareStatement",
            "setObject",
            "setObject#2",
            "executeQuery",
            "next",
            "getString",
            "getObject",
            "getBytes",
            "resultClose",
            "statementClose",
            "commit",
            "close")) {
      reset();
      try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
        seed(f, LOGIN, "0101");
        var probe = new MaintenanceJdbcProbe();
        probe.fault = fault;
        redacted(() -> probed(f, probe).inspectNext(RUN, Optional.empty()));
        assertEquals(1, probe.closes, fault);
        assertEquals(fault.equals("close") ? "0" : "1", count(), fault);
      }
    }
    for (String selected :
        List.of("maintenance_next_inbox", "maintenance_delete_inbox", "inspection_health")) {
      for (String fault : List.of("executeQuery", "resultClose", "statementClose")) {
        reset();
        try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
          seed(f, LOGIN, "0101");
          var p = new MaintenanceJdbcProbe();
          p.selectedSql = selected;
          p.fault = fault;
          redacted(() -> probed(f, p).inspectNext(RUN, Optional.empty()));
          assertTrue(p.selectedStatements >= 1, selected);
          assertEquals("1", count());
          assertEquals(1, p.rollbacks);
          assertEquals(1, p.closes);
        }
      }
      for (String mode : List.of("empty", "duplicate", "null")) {
        reset();
        try (var f = new AuthenticationInboxInspectorTest.Fixture()) {
          seed(f, LOGIN, "0101");
          var p = new MaintenanceJdbcProbe();
          p.selectedSql = selected;
          p.empty = mode.equals("empty");
          p.duplicate = mode.equals("duplicate");
          if (mode.equals("null"))
            p.columns.put(
                selected.equals("inspection_health")
                    ? "inspection_health"
                    : selected.contains("delete") ? "deleted" : "message_id",
                null);
