                    return "OK";
                  } catch (SQLException failure) {
                    return failure.getSQLState();
                  }
                }
              });
        }
        var results = new ArrayList<String>();
        for (var done : pool.invokeAll(race)) results.add(done.get(10, TimeUnit.SECONDS));
