      assertEquals(100, attempts);
      assertEquals(3, deleted.size());
      assertEquals(
          Set.of(new UUID(0, 101), new UUID(0, 102), new UUID(0, 103)), new HashSet<>(deleted));
      assertEquals("0", count());
