    try (var c = locked();
        var admin = db.admin()) {
      for (String zone : List.of("UTC", "Asia/Tokyo", "America/New_York")) {
        sql(c, "set timezone='" + zone + "'");
        for (String literal :
            List.of(
                "0001-01-01T00:00:00Z",
                "1582-10-05T00:00:00Z",
                "1582-10-15T00:00:00Z",
