          insert(admin, literal, 0, 0, 0, false);
          assertEquals(List.of(0L, 0L, 0L, false), read(c, RUN, literal), zone + "/" + literal);
          assertEquals(List.of(), read(c, new UUID(0, 99), literal));
        }
        for (String at :
            List.of(
