      sql(admin, "delete from schubert.inbox_inspection_progress");
      insert(admin, TIME, 0, 0, 0, false);
      assertEquals(
          "55000",
          assertThrows(SQLException.class, () -> read(c, RUN, "2026-09-12T15:00:00.123457Z"))
              .getSQLState());
