    var out = new ByteArrayOutputStream();
    var err = new ByteArrayOutputStream();
    try (var output = new PrintStream(out, false, StandardCharsets.UTF_8);
        var diagnostics = new PrintStream(err, false, StandardCharsets.UTF_8)) {
