        70,
        launcher.run(
            new String[0],
            environment(),
            s ->
                r -> {
                  throw new NoSuchAlgorithmException("UNTRUSTED_SECRET");
                }));
    assertEquals(
        50,
        launcher.run(
            new String[0],
            environment(),
            s ->
                r -> {
                  throw new IOException("UNTRUSTED_SECRET");
