  private static void seedPrefix() throws SQLException {
    try (var c = db.admin()) {
      log(c, 1, "'2026-06-01'", "'2026-10-01'");
      log(c, 2, "'2026-06-02'", "'2026-10-01'");
      log(c, 3, "'2026-06-03'", "null");
    }
